<?php

declare(strict_types=1);

namespace Database\Seeders;

use App\Models\GrammarCategory;
use App\Models\GrammarPattern;
use App\Models\GrammarPatternExample;
use Illuminate\Database\Seeder;

/**
 * Pattern content for the Grammar system. Each entry names its category by
 * (level, category name) — GrammarStructureSeeder must run first so those
 * rows exist. Re-running is safe: patterns are looked up by title within
 * their category and updated in place rather than duplicated.
 */
class GrammarPatternSeeder extends Seeder
{
    public function run(): void
    {
        $count = 0;
        $skipped = 0;

        // Japanese title/sentence -> romaji, generated offline via a proper
        // morphological romanizer (cutlet/fugashi) — see the file header for
        // how to regenerate. Keyed by exact string match against the source
        // arrays below, so it stays correct even as new patterns are added
        // (a miss just means no romaji for that one string, not a crash).
        $romaji = require database_path('seeders/data/grammar_romaji_map.php');

        // Each set is scoped to one (language, track) tree — level names like
        // "N5" or "Beginner" are now reused across trees, so the category
        // lookup below must filter by language+track too, not just level name.
        $sets = [
            ['language' => 'japanese', 'track' => 'grammar', 'patterns' => $this->n5Patterns()],
            ['language' => 'japanese', 'track' => 'grammar', 'patterns' => $this->n4Patterns()],
            ['language' => 'japanese', 'track' => 'grammar', 'patterns' => $this->n3Patterns()],
            ['language' => 'japanese', 'track' => 'grammar', 'patterns' => $this->n2Patterns()],
            ['language' => 'japanese', 'track' => 'grammar', 'patterns' => $this->n1Patterns()],
            ['language' => 'english', 'track' => 'grammar', 'patterns' => $this->englishGrammarBeginnerPatterns()],
            ['language' => 'english', 'track' => 'grammar', 'patterns' => $this->englishGrammarElementaryPatterns()],
            ['language' => 'english', 'track' => 'grammar', 'patterns' => $this->englishGrammarIntermediatePatterns()],
            ['language' => 'english', 'track' => 'grammar', 'patterns' => $this->englishGrammarUpperIntermediatePatterns()],
            ['language' => 'english', 'track' => 'grammar', 'patterns' => $this->englishGrammarAdvancedPatterns()],
            ['language' => 'japanese', 'track' => 'structure', 'patterns' => $this->japaneseStructureN5Patterns()],
            ['language' => 'japanese', 'track' => 'structure', 'patterns' => $this->japaneseStructureN4Patterns()],
            ['language' => 'japanese', 'track' => 'structure', 'patterns' => $this->japaneseStructureN3Patterns()],
            ['language' => 'japanese', 'track' => 'structure', 'patterns' => $this->japaneseStructureN2Patterns()],
            ['language' => 'japanese', 'track' => 'structure', 'patterns' => $this->japaneseStructureN1Patterns()],
            ['language' => 'english', 'track' => 'structure', 'patterns' => $this->englishStructureBeginnerPatterns()],
            ['language' => 'english', 'track' => 'structure', 'patterns' => $this->englishStructureElementaryPatterns()],
            ['language' => 'english', 'track' => 'structure', 'patterns' => $this->englishStructureIntermediatePatterns()],
            ['language' => 'english', 'track' => 'structure', 'patterns' => $this->englishStructureUpperIntermediatePatterns()],
            ['language' => 'english', 'track' => 'structure', 'patterns' => $this->englishStructureAdvancedPatterns()],
        ];

        foreach ($sets as $set) {
            foreach ($set['patterns'] as $level => $entries) {
                foreach ($entries as $entry) {
                    $category = GrammarCategory::whereHas('level', fn ($q) => $q
                        ->where('name', $level)
                        ->where('language', $set['language'])
                        ->where('track', $set['track']))
                        ->where('name', $entry['category'])
                        ->first();

                    if (! $category) {
                        $skipped++;

                        continue;
                    }

                    // No explicit `slug` here — HasSlug's boot hook generates a
                    // *unique* one from the title on create. Setting it manually
                    // via Str::slug() is unsafe for mixed Japanese/Latin titles:
                    // e.g. "AはBが好きです" and "AはBです" both collapse to "ab",
                    // which collided on the unique index.
                    $pattern = GrammarPattern::updateOrCreate(
                        ['grammar_category_id' => $category->id, 'title' => $entry['title']],
                        [
                            'title_romaji' => $set['language'] === 'japanese' ? ($romaji[$entry['title']] ?? null) : null,
                            'explanation' => $entry['explanation'],
                            'formula' => $entry['formula'] ?? null,
                            'is_published' => true,
                            'published_at' => now(),
                        ],
                    );

                    $pattern->items()->delete();

                    foreach (array_values($entry['items']) as $i => $item) {
                        GrammarPatternExample::create([
                            'grammar_pattern_id' => $pattern->id,
                            'type' => $item['type'],
                            'sentence' => $item['sentence'],
                            'romaji' => $set['language'] === 'japanese' ? ($romaji[$item['sentence']] ?? null) : null,
                            'translation' => $item['translation'] ?? null,
                            'correction' => $item['correction'] ?? null,
                            'correction_romaji' => $set['language'] === 'japanese' ? ($romaji[$item['correction'] ?? ''] ?? null) : null,
                            'note' => $item['note'] ?? null,
                            'sort_order' => $i,
                        ]);
                    }

                    $count++;
                }
            }
        }

        $this->command?->info("  grammar patterns: {$count} dibuat/diperbarui, {$skipped} dilewati (kategori tidak ditemukan)");
    }

