                    'items' => [
                        ['type' => 'example', 'sentence' => 'If he really loved his job, he wouldn\'t have quit so abruptly last week.', 'translation' => 'Seandainya dia benar-benar mencintai pekerjaannya, dia tidak akan berhenti begitu mendadak minggu lalu.'],
                        ['type' => 'example', 'sentence' => 'If she were as competent as they claim, the project wouldn\'t have failed under her leadership.', 'translation' => 'Seandainya dia sekompeten yang mereka klaim, proyek itu tidak akan gagal di bawah kepemimpinannya.'],
                        ['type' => 'example', 'sentence' => 'If the evidence were reliable, the jury wouldn\'t have acquitted the defendant.', 'translation' => 'Seandainya bukti itu dapat diandalkan, juri tidak akan membebaskan terdakwa itu.'],
                        ['type' => 'example', 'sentence' => 'If the theory were correct, the experiment wouldn\'t have produced such contradictory results.', 'translation' => 'Seandainya teori itu benar, eksperimen itu tidak akan menghasilkan hasil yang begitu kontradiktif.'],
                        ['type' => 'mistake', 'sentence' => 'If he is honest, he wouldn\'t have lied to the committee last year.', 'correction' => 'If he were honest, he wouldn\'t have lied to the committee last year.', 'note' => 'Klausa if yang menyatakan sifat hipotetis masa kini memerlukan simple past/subjunctive ("were"), bukan simple present ("is"), agar konsisten dengan sifat kontrafaktual dari mixed conditional ini.'],
